mapper.select:
SELECT COUNT(*) FROM `org`
WHERE active_name_key = #{name}
AND id != #{excludeId}

SELECT active_name_key FROM `org`
WHERE active_name_key IN
#{candidate}

SELECT * FROM `org`

ORDER BY gmt_create DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.sql:
WHERE o.is_deleted = 0 AND o.status = 0 AND o.id != #{sourceWorkspaceId}
AND o.name LIKE CONCAT('%', #{keyword}, '%')
AND EXISTS (SELECT 1 FROM org_member m JOIN workspace_role r ON r.id = m.role_id AND r.tenant_id = m.tenant_id AND r.is_deleted = 0 WHERE m.tenant_id = o.id AND m.user_id = #{userId} AND m.status = 0 AND m.is_deleted = 0 AND r.access_level IN ('READ_WRITE', 'ADMIN'))

mapper.select:
SELECT o.* FROM `org` o

ORDER BY o.gmt_create DESC, o.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT o.* FROM `org` o

ORDER BY o.deleted_at DESC, o.id DESC
LIMIT #{limit} OFFSET #{offset}
